Destrucción tipo Shaw: relaciona clientes por distancia, demanda y pertenencia a la misma ruta, y libera sus arcos más los que reconectan a sus vecinos de ruta.

```python
from random import Random

COMPONENT = {
    "name": "shaw_related_arc_destruction",
    "slot": "destruction",
    "compatible_skeletons": ["LNS_MIP", "MIP_PERTURB"],
    "requires": ["ProblemModel.to_assignment"],
    "params": {
        "determinism": {"type": "float", "range": [1.0, 10.0]},
        "demand_weight": {"type": "float", "range": [0.0, 1.0]},
        "route_weight": {"type": "float", "range": [0.0, 1.0]},
    },
}


def _xn(i, j):
    return f"x_{i}_{j}"


def _routes(assignment, N):
    succ, pred, starts = {}, {}, []
    for i in range(N):
        for j in range(N):
            if i != j and assignment.get(_xn(i, j), 0.0) > 0.5:
                if i == 0:
                    starts.append(j)
                else:
                    succ.setdefault(i, j)
                if j != 0:
                    pred.setdefault(j, i)
    routes, seen = [], set()
    for s in starts:
        r, c, steps = [], s, 0
        while c != 0 and c not in seen and steps <= N:
            seen.add(c)
            r.append(c)
            c = succ.get(c, 0)
            steps += 1
        if r:
            routes.append(r)
    return routes, succ, pred


def _free_arcs(S, succ, pred, N, assignment):
    A = {0}
    for c in S:
        A.add(c)
        A.add(succ.get(c, 0))
        A.add(pred.get(c, 0))
    free = set()
    for c in S:
        for i in range(N):
            if i != c:
                free.add(_xn(i, c))
                free.add(_xn(c, i))
    for a in A:
        for b in A:
            if a != b:
                free.add(_xn(a, b))
    return {v for v in free if v in assignment}


class ShawRelatedArcDestruction:
    """Selección iterativa de clientes relacionados (Shaw) y liberación de sus arcos."""

    def __init__(self, problem, inst, determinism, demand_weight, route_weight):
        self.problem, self.inst = problem, inst
        self.p = float(determinism)
        self.wd = float(demand_weight)
        self.wr = float(route_weight)

    def destroy(self, sol, ratio: float, rng: Random):
        inst = self.inst
        assignment = self.problem.to_assignment(sol)
        N = len(inst.coords)
        n = N - 1
        if n <= 0 or not assignment:
            v = next(iter(assignment)) if assignment else None
            free = {v} if v is not None else set()
            return {k: val for k, val in assignment.items() if k not in free}, free
        k = min(n, max(1, int(round(ratio * n))))
        routes, succ, pred = _routes(assignment, N)
        rid = {}
        for idx, r in enumerate(routes):
            for c in r:
                rid[c] = idx
        dist = inst.dist
        dem = inst.demand
        maxd = max(1e-9, max(dist(i, j) for i in range(1, N) for j in range(1, N)) if n > 1 else 1.0)
        maxq = max(1e-9, max(dem[c] for c in range(1, N)))

        def rel(a, b):
            r = dist(a, b) / maxd + self.wd * abs(dem[a] - dem[b]) / maxq
            if rid.get(a, -1) != rid.get(b, -2):
                r += self.wr
            return r

        seed = rng.randint(1, n)
        removed = [seed]
        rem_set = {seed}
        while len(removed) < k:
            ref = rng.choice(removed)
            cand = sorted((c for c in range(1, N) if c not in rem_set), key=lambda c: (rel(ref, c), c))
            if not cand:
                break
            idx = int((rng.random() ** self.p) * len(cand))
            c = cand[min(idx, len(cand) - 1)]
            removed.append(c)
            rem_set.add(c)
        free = _free_arcs(rem_set, succ, pred, N, assignment)
        if not free:
            free = {next(iter(assignment))}
        partial = {v: val for v, val in assignment.items() if v not in free}
        return partial, free


def build_component(problem, determinism=4.0, demand_weight=0.3, route_weight=0.2):
    return ShawRelatedArcDestruction(problem, problem.inst, determinism, demand_weight, route_weight)
```

Destrucción por rutas completas: elige una ruta semilla y añade rutas vecinas según la distancia entre centroides hasta cubrir la cuota, y libera todos sus arcos para que el sub-MIP las re-enrute.

```python
from random import Random

COMPONENT = {
    "name": "route_cluster_destruction",
    "slot": "destruction",
    "compatible_skeletons": ["LNS_MIP", "MIP_PERTURB"],
    "requires": ["ProblemModel.to_assignment"],
    "params": {
        "random_route_prob": {"type": "float", "range": [0.0, 0.5]},
        "overshoot": {"type": "bool", "values": [True, False]},
    },
}


def _xn(i, j):
    return f"x_{i}_{j}"


def _routes(assignment, N):
    succ, pred, starts = {}, {}, []
    for i in range(N):
        for j in range(N):
            if i != j and assignment.get(_xn(i, j), 0.0) > 0.5:
                if i == 0:
                    starts.append(j)
                else:
                    succ.setdefault(i, j)
                if j != 0:
                    pred.setdefault(j, i)
    routes, seen = [], set()
    for s in starts:
        r, c, steps = [], s, 0
        while c != 0 and c not in seen and steps <= N:
            seen.add(c)
            r.append(c)
            c = succ.get(c, 0)
            steps += 1
        if r:
            routes.append(r)
    rest = [c for c in range(1, N) if c not in seen]
    for c in rest:
        routes.append([c])
    return routes, succ, pred


def _free_arcs(S, succ, pred, N, assignment):
    A = {0}
    for c in S:
        A.add(c)
        A.add(succ.get(c, 0))
        A.add(pred.get(c, 0))
    free = set()
    for c in S:
        for i in range(N):
            if i != c:
                free.add(_xn(i, c))
                free.add(_xn(c, i))
    for a in A:
        for b in A:
            if a != b:
                free.add(_xn(a, b))
    return {v for v in free if v in assignment}


class RouteClusterDestruction:
    """Libera rutas completas cercanas (por centroide) a una ruta semilla."""

    def __init__(self, problem, inst, random_route_prob, overshoot):
        self.problem, self.inst = problem, inst
        self.prand = float(random_route_prob)
        self.overshoot = bool(overshoot)

    def destroy(self, sol, ratio: float, rng: Random):
        inst = self.inst
        assignment = self.problem.to_assignment(sol)
        N = len(inst.coords)
        n = N - 1
        if n <= 0 or not assignment:
            free = {next(iter(assignment))} if assignment else set()
            return {k: v for k, v in assignment.items() if k not in free}, free
        k = min(n, max(1, int(round(ratio * n))))
        routes, succ, pred = _routes(assignment, N)
        coords = inst.coords
        cents = []
        for r in routes:
            cx = sum(coords[c][0] for c in r) / len(r)
            cy = sum(coords[c][1] for c in r) / len(r)
            cents.append((cx, cy))
        seed = rng.randrange(len(routes))
        chosen = [seed]
        S = set(routes[seed])
        remaining = [i for i in range(len(routes)) if i != seed]
        sx, sy = cents[seed]
        remaining.sort(key=lambda i: ((cents[i][0] - sx) ** 2 + (cents[i][1] - sy) ** 2, i))
        while len(S) < k and remaining:
            if rng.random() < self.prand:
                idx = rng.randrange(len(remaining))
            else:
                idx = 0
            ri = remaining.pop(idx)
            r = routes[ri]
            if not self.overshoot and len(S) + len(r) > k:
                need = k - len(S)
                start = rng.randrange(len(r) - need + 1)
                S.update(r[start:start + need])
                break
            chosen.append(ri)
            S.update(r)
        free = _free_arcs(S, succ, pred, N, assignment)
        if not free:
            free = {next(iter(assignment))}
        partial = {v: val for v, val in assignment.items() if v not in free}
        return partial, free


def build_component(problem, random_route_prob=0.15, overshoot=True):
    return RouteClusterDestruction(problem, problem.inst, random_route_prob, overshoot)
```

Destrucción por peor desvío: libera los clientes cuya eliminación ahorraría más distancia, d(p,c)+d(c,s)−d(p,s), con un sesgo aleatorio por rango.

